import numpy as npimport matplotlib.pyplot as pltimport tensorflow as tffrom tensorflow.keras.layers import Dense, Flattenfrom tensorflow.keras.models import Modelfrom tensorflow.keras.applications.resnet50 import ResNet50from tensorflow.keras.preprocessing.image import ImageDataGeneratorfrom glob import globfrom keras.callbacks import ModelCheckpoint, ReduceLROnPlateau, EarlyStoppingimage_size = 224test_images_folder = "./kaggle/chest_xray/test"train_images_folder = "./kaggle/chest_xray/train"validation_images_folder = ".kaggle/chest_xray/val"my_resnet = ResNet50(input_shape = [image_size, image_size, 3], weights = "imagenet", include_top = False)for layer in my_resnet.layers:  layer.trainable = Falseclasses = glob('./kaggle/chest_xray/test/*')num_of_classes = len(classes)global_avg_pooling_layer = tf.keras.layers.GlobalAveragePooling2D()(my_resnet.output)PlusFlattenLayer = Flatten()(global_avg_pooling_layer)prediction_layer = Dense(num_of_classes, activation="softmax")(PlusFlattenLayer)model = Model(inputs = my_resnet.input, outputs = prediction_layer)model.compile(loss = "categorical_crossentropy", optimizer = tf.keras.optimizers.Adam(learning_rate=0.01), metrics=["recall"])test_datagen = ImageDataGenerator(rescale = 1./255)training_datagen = ImageDataGenerator(rescale = 1./255,                                      shear_range = 0.2,                                      zoom_range = 0.2,                                      horizontal_flip = True)trainning_set = training_datagen.flow_from_directory(train_images_folder,                                                     target_size = (224,224),                                                     batch_size = 32,                                                     class_mode = "categorical")validation_set = test_datagen.flow_from_directory(validation_images_folder,                                                     target_size = (224,224),                                                     batch_size = 32,                                                     class_mode = "categorical")EPOCHS = 30best_model_file = "./pneunomia_model.h5"from keras.callbacks import ModelCheckpoint, ReduceLROnPlateau, EarlyStoppingcallbacks = [ModelCheckpoint(best_model_file, verbose = 1, save_best_only = True, monitor = "val_recall"),             ReduceLROnPlateau(monitor = "val_recall", patience = 10, factor = 0.1, verbose = 1, min_lr = 1e-6),             EarlyStopping(monitor = "val_recall", patience = 30, verbose = 1)]r = model.fit(    trainning_set,    validation_data = validation_set,    epochs = EPOCHS,    steps_per_epoch = len(trainning_set),    validation_steps = len(validation_set),    callbacks = callbacks)model.save("./pneunomia_smart_model.keras")